<script setup lang="ts">
import { useQuery } from '@tanstack/vue-query'
import { ArrowRight, BadgeCheck } from '@lucide/vue'
import { NPagination } from 'naive-ui'
import { computed, ref } from 'vue'
import { RouterLink } from 'vue-router'
import { formatDate, serviceStatus, shopApi } from '../lib'
const page=ref(1);const query=useQuery({queryKey:computed(()=>['shop-services',page.value]),queryFn:()=>shopApi.services(page.value)});const pages=computed(()=>Math.max(1,Math.ceil(Number(query.data.value?.total??0)/20)))
</script>
<template><section class="service-list-page"><header><p>MY BENEFITS</p><h1 tabindex="-1">我的服务</h1><span>每一次权益都是独立服务，可分开选择接单人并核销。</span></header><div v-if="query.isPending.value" class="service-state" role="status">正在读取服务…</div><div v-else-if="query.isError.value" class="service-state" role="alert"><button @click="query.refetch()">加载失败，重试</button></div><div v-else-if="query.data.value?.list.length" class="service-list"><RouterLink v-for="item in query.data.value.list" :key="item.id" :to="`/services/${item.id}`"><BadgeCheck :size="24"/><div><small>#{{item.id}} · {{serviceStatus(item.status)}}</small><strong>{{item.service.name}}</strong><span v-if="item.expire_time">有效至 {{formatDate(item.expire_time)}}</span><span v-else>长期有效</span></div><ArrowRight :size="19"/></RouterLink></div><div v-else class="service-state"><BadgeCheck :size="32"/><h2>暂无可用服务</h2><p>购买服务套餐或领取服务卡密后，权益会出现在这里。</p></div><div v-if="query.data.value?.total" class="service-pager"><span>第 {{page}} / {{pages}} 页</span><NPagination v-model:page="page" :page-count="pages"/></div></section></template>
<style scoped>.service-list-page{width:min(980px,calc(100% - 32px));margin:0 auto;padding:64px 0 96px}.service-list-page>header{max-width:680px;margin-bottom:32px}.service-list-page h1{margin:8px 0;font-size:clamp(2rem,5vw,3.8rem)}.service-list-page header p,.service-list-page small{color:#69e4dc;letter-spacing:.1em}.service-list-page header span,.service-list span{color:#9fb0c5}.service-list{display:grid;overflow:hidden;border-block:1px solid #263951}.service-list a{min-height:96px;display:grid;grid-template-columns:auto 1fr auto;gap:16px;align-items:center;padding:18px 8px;color:#f5f7fb;border-bottom:1px solid #263951}.service-list a:last-child{border-bottom:0}.service-list a:hover{background:rgba(105,228,220,.05)}.service-list strong,.service-list span{display:block;margin-top:5px}.service-state{min-height:190px;display:grid;place-items:center;align-content:center;gap:.65rem;padding:40px;text-align:center;border-block:1px solid #263951}.service-pager{display:flex;align-items:center;justify-content:space-between;gap:1rem;margin-top:24px;color:#9fb0c5}@media(max-width:700px){.service-list-page{padding-top:36px}.service-pager{align-items:flex-start;flex-direction:column}}</style>
